import{_ as n,o as r,c as g,a3 as d}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Bảng thuật ngữ","description":"","frontmatter":{},"headers":[],"relativePath":"phu-luc/thuat-ngu.md","filePath":"phu-luc/thuat-ngu.md","lastUpdated":1782143716000}'),h={name:"phu-luc/thuat-ngu.md"};function o(i,t,s,c,a,e){return r(),g("div",null,[...t[0]||(t[0]=[d('<h1 id="bang-thuat-ngu" tabindex="-1">Bảng thuật ngữ <a class="header-anchor" href="#bang-thuat-ngu" aria-label="Permalink to &quot;Bảng thuật ngữ&quot;">​</a></h1><p>Giải thích các thuật ngữ và viết tắt xuất hiện trong FADO AssetFlow.</p><table tabindex="0"><thead><tr><th>Thuật ngữ</th><th>Giải thích</th></tr></thead><tbody><tr><td><strong>RBAC</strong></td><td><em>Role-Based Access Control</em> — phân quyền theo vai trò. Quyền truy cập từng module được cấp theo vai trò của người dùng, không gán trực tiếp cho từng người.</td></tr><tr><td><strong>Vai trò (Role)</strong></td><td>Nhóm quyền của người dùng. Bốn vai trò chính: <strong>Super Admin</strong>, <strong>Admin</strong>, <strong>Quản lý</strong>, <strong>Người dùng</strong>.</td></tr><tr><td><strong>Super Admin</strong></td><td>Vai trò cao nhất; truy cập mọi module kể cả cấu hình hệ thống (ví dụ Cấu hình Ticket).</td></tr><tr><td><strong>Admin</strong></td><td>Quản trị viên nghiệp vụ; quản lý phần lớn module nhưng không thấy một số mục dành riêng Super Admin.</td></tr><tr><td><strong>Module</strong></td><td>Một nhóm chức năng của hệ thống (Tài sản, Ticket, Chấm công, Nhân sự...). Quyền được cấp theo từng module.</td></tr><tr><td><strong>ADMS</strong></td><td><em>Automatic Data Master Server</em> — giao thức để máy chấm công ZKTeco/Ronald Jack <strong>đẩy (push)</strong> dữ liệu chấm công ra server qua HTTP/HTTPS.</td></tr><tr><td><strong>Pull (kéo)</strong></td><td>Chế độ server <strong>chủ động kết nối vào máy</strong> chấm công (TCP/IP) để lấy dữ liệu; yêu cầu server cùng mạng LAN với máy.</td></tr><tr><td><strong>Push (đẩy)</strong></td><td>Chế độ máy <strong>chủ động gửi dữ liệu ra</strong> server (qua ADMS); phù hợp khi server đặt trên cloud.</td></tr><tr><td><strong>Mapping (gán mã)</strong></td><td>Liên kết mã chấm công/PIN trên máy với nhân viên trong hệ thống, để dữ liệu chấm công hiển thị đúng người.</td></tr><tr><td><strong>PIN / Mã chấm công</strong></td><td>Mã định danh nhân viên trên máy chấm công. Nếu trùng <strong>Mã nhân viên</strong> trong hệ thống thì tự khớp (auto-map).</td></tr><tr><td><strong>SN (Serial Number)</strong></td><td>Số serial của máy chấm công, dùng làm <strong>Mã máy</strong> khi khai báo máy trong webapp.</td></tr><tr><td><strong>Bù công</strong></td><td>Khai báo điều chỉnh khi nhân viên quên/lỗi chấm công, để bổ sung dữ liệu công thiếu.</td></tr><tr><td><strong>Tăng ca</strong></td><td>Thời gian làm thêm ngoài ca làm việc chuẩn.</td></tr><tr><td><strong>Onboarding</strong></td><td>Quy trình tiếp nhận nhân viên mới (tạo hồ sơ, cấp tài sản, tài khoản...).</td></tr><tr><td><strong>Offboarding</strong></td><td>Quy trình nghỉ việc (thu hồi tài sản, vô hiệu tài khoản...).</td></tr><tr><td><strong>ATS</strong></td><td><em>Applicant Tracking System</em> — hệ thống theo dõi ứng viên trong quy trình tuyển dụng.</td></tr><tr><td><strong>JD</strong></td><td><em>Job Description</em> — bản mô tả công việc của một vị trí tuyển dụng.</td></tr><tr><td><strong>CV</strong></td><td><em>Curriculum Vitae</em> — hồ sơ ứng viên.</td></tr><tr><td><strong>Ticket</strong></td><td>Yêu cầu hỗ trợ / tác vụ nội bộ toàn doanh nghiệp, hướng tới mô hình xử lý công việc kiểu ERP.</td></tr><tr><td><strong>Task (Công việc)</strong></td><td>Đầu việc được giao cho nhân viên, theo dõi trạng thái và tiến độ.</td></tr><tr><td><strong>SSE</strong></td><td><em>Server-Sent Events</em> — kỹ thuật server đẩy dữ liệu realtime về trình duyệt (dùng cho cập nhật chấm công, thông báo tức thời).</td></tr><tr><td><strong>Migration</strong></td><td>Tệp SQL đánh số thứ tự (<code>migrations/NNN_*.sql</code>) thay đổi cấu trúc database; chạy một lần khi triển khai.</td></tr><tr><td><strong>reconcile.sql</strong></td><td>Tệp SQL dựng/đồng bộ schema chạy <strong>sau</strong> các migration đánh số khi khởi động; mọi thay đổi constraint phải cập nhật cả hai nơi.</td></tr><tr><td><strong>Distribution List</strong></td><td>Nhóm mail — danh sách địa chỉ email nhận chung một thư.</td></tr><tr><td><strong>Coolify</strong></td><td>Nền tảng PaaS self-hosted dùng để build và triển khai ứng dụng từ GitHub.</td></tr><tr><td><strong>Standalone</strong></td><td>Chế độ đóng gói của Next.js tạo bản chạy độc lập, dùng khi triển khai bằng Docker.</td></tr></tbody></table>',3)])])}const l=n(h,[["render",o]]);export{m as __pageData,l as default};
